import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    cache = {}
    last_access = {}

    def memoized_function(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key in cache:
            if timer() - last_access[key] > ttl:
                del cache[key]
                del last_access[key]
            else:
                return cache[key]
        result = cache[key] = memoized_function(*args, **kwargs)
        last_access[key] = timer()
        if len(cache) > maxsize:
            oldest_key = min(last_access, key=last_access.get)
            del cache[oldest_key]
            del last_access[oldest_key]
        return result

    return memoized_function

